#!/usr/bin/env python3
"""
从 pcap 提取的关键帧原始字节
自动生成，不要手动修改
"""

# 登录帧 (770 字节)
LOGIN_FRAME = bytes.fromhex("")

# 订阅帧 (包含 stockcode)  
SUBSCRIBE_FRAME = bytes.fromhex("")

# 股票池订阅帧 (多 stockcode)
def get_login_frame():
    """获取登录帧"""
    return LOGIN_FRAME

def get_subscribe_frame():
    """获取订阅帧"""
    return SUBSCRIBE_FRAME
